    bh_re = re.compile(r"spin_lock_(?:bh|irqsave|irq|irqrestore|nested|nested_bh)\s*\(\s*&?([^);]+?)\s*[,)]")
    for ln, lock, kind in extract_locks(path, plain_re, bh_re):
        print(f"{ln}\t{kind}\t{lock}")
